import { useEffect, useState, type FormEvent, type ReactNode } from 'react'
import {
  ArrowDownLeft, ArrowLeft, ArrowRight, ArrowUpRight, Bell, Bot, BriefcaseBusiness, CalendarDays,
  Check, CheckCheck, ChevronDown, ChevronLeft, ChevronRight, CreditCard, Filter, Headphones,
  LayoutDashboard, LogOut, Menu, MessageCircle, MoreHorizontal, Package, Plus, Search, Send, Settings,
  ShieldCheck, Sparkles, Users, Wallet, X, MapPin, Plane, Clock3, CircleDollarSign, Banknote,
  Copy, ExternalLink, RotateCcw, Eye, Link2, QrCode, Landmark,
} from 'lucide-react'
import { createInitialState, DEMO_FX_ARS_PER_USD } from './data'
import { agencyNet, feeFor, paymentSettlement, refundNet, seatsAfterConfirmation, releaseSeats, convertCurrency } from './services/money'
import { BELO_TOOLS } from './services/belo/tools'
import { MockBeloMcpServer } from './services/belo/client'
import type { AppState, Booking, Conversation, Currency, McpCall, PackageItem, Page, Role } from './types'

const STORE_KEY = 'piluso-demo-state-v1'
const usd = (amount: number) => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(amount)
const ars = (amount: number) => new Intl.NumberFormat('es-AR', { style: 'currency', currency: 'ARS', maximumFractionDigits: 0 }).format(amount)
const money = (amount: number, currency: Currency) => currency === 'ARS' ? ars(amount) : usd(amount)
const fxRateLabel = () => `1 USD = ${new Intl.NumberFormat('es-AR').format(DEMO_FX_ARS_PER_USD)} ARS`
const timeNow = () => new Date().toLocaleTimeString('es-AR', { hour: '2-digit', minute: '2-digit' })
const newId = (prefix: string) => `${prefix}-${Date.now()}-${Math.floor(Math.random() * 1000)}`

function readState(): AppState {
  try {
    const raw = localStorage.getItem(STORE_KEY)
    if (raw) return { ...createInitialState(), ...JSON.parse(raw), role: location.hash.startsWith('#viajero/') ? 'traveler' : (sessionStorage.getItem('piluso-demo-role') as Role) ?? 'owner' } as AppState
  } catch { /* corrupted or unavailable local storage falls back to the demo seed */ }
  return createInitialState()
}

function Logo({ compact = false }: { compact?: boolean }) {
  return <span className={`brand ${compact ? 'brand-compact' : ''}`} aria-label="Piluso"><img className="brand-logo" src="./logo-piluso.png" alt="Piluso" /></span>
}

const nav: { id: Page; label: string; icon: typeof LayoutDashboard }[] = [
  { id: 'overview', label: 'Overview', icon: LayoutDashboard }, { id: 'packages', label: 'Paquetes', icon: Package },
  { id: 'bookings', label: 'Reservas', icon: BriefcaseBusiness }, { id: 'conversations', label: 'Conversaciones', icon: MessageCircle },
  { id: 'payments', label: 'Pagos', icon: Wallet }, { id: 'settings', label: 'Configuración', icon: Settings },
]

function App() {
  const [state, setState] = useState<AppState>(() => { const initial = readState(); if (location.hash.startsWith('#viajero/')) initial.role = 'traveler'; return initial })
  const [loggedIn, setLoggedIn] = useState(() => sessionStorage.getItem('piluso-demo-session') === 'active' || location.hash.startsWith('#viajero/'))
  const [page, setPage] = useState<Page>('overview')
  const [mobileNav, setMobileNav] = useState(false)
  const [assistantOpen, setAssistantOpen] = useState(false)
  const [noticeOpen, setNoticeOpen] = useState(false)
  const [customerOpen, setCustomerOpen] = useState<string | null>(null)
  const [modal, setModal] = useState<'package' | 'booking' | 'customer' | null>(null)
  const [editingPackage, setEditingPackage] = useState<PackageItem | null>(null)
  const [previewPackage, setPreviewPackage] = useState<PackageItem | null>(null)
  const [selectedBooking, setSelectedBooking] = useState<string | null>(null)
  const [toast, setToast] = useState('')
  const [search, setSearch] = useState('')
  const [paymentTab, setPaymentTab] = useState('Balance y movimientos')
  const [notificationsSeen, setNotificationsSeen] = useState(false)

  useEffect(() => {
    const sharedState = { ...state, role: undefined }
    localStorage.setItem(STORE_KEY, JSON.stringify(sharedState))
  }, [state])
  useEffect(() => {
    const onStorage = (event: StorageEvent) => { if (event.key === STORE_KEY && event.newValue) setState({ ...createInitialState(), ...JSON.parse(event.newValue), role: location.hash.startsWith('#viajero/') ? 'traveler' : (sessionStorage.getItem('piluso-demo-role') as Role) ?? 'owner' }) }
    window.addEventListener('storage', onStorage)
    return () => window.removeEventListener('storage', onStorage)
  }, [])
  useEffect(() => { if (!toast) return; const id = window.setTimeout(() => setToast(''), 3200); return () => window.clearTimeout(id) }, [toast])

  const update = (mutator: (prev: AppState) => AppState) => setState(prev => mutator(prev))
  const notify = (title: string, detail: string, whatsapp = false) => update(prev => ({ ...prev, notices: [{ id: newId('notice'), title, detail: whatsapp ? `${detail} · WhatsApp simulado` : detail, time: 'Ahora', read: false }, ...prev.notices] }))
  const callBelo = async (tool: string, args: Record<string, unknown>) => {
    let output: unknown
    let status: McpCall['status'] = 'ok'
    try {
      output = await new MockBeloMcpServer(() => state, (name, payload) => performBeloAction(name, payload)).callTool(tool, args)
    } catch (error) { output = { error: error instanceof Error ? error.message : 'Error' }; status = 'error' }
    const call: McpCall = { id: newId('mcp'), tool, request: args, response: output, status, at: timeNow() }
    update(prev => ({ ...prev, calls: [call, ...prev.calls] }))
    return output
  }
  const performBeloAction = (name: string, args: Record<string, unknown>) => {
    if (name === BELO_TOOLS.sendBankTransfer || name === BELO_TOOLS.sendBeloTransfer) {
      const ids = args.ids as string[] ?? []
      update(prev => {
        const rows = prev.supplierPayments.filter(row => ids.includes(row.id) && row.status === 'Pendiente')
        const nextBalances = { ...prev.balances }
        rows.forEach(row => { nextBalances[row.currency] -= row.amount })
        return { ...prev, balances: nextBalances,
          supplierPayments: prev.supplierPayments.map(row => ids.includes(row.id) ? { ...row, status: 'Pagada' } : row),
          transactions: [...rows.map(row => ({ id: newId('tx'), date: new Date().toISOString().slice(0, 10), kind: 'Pago a proveedor', detail: row.concept, amount: -row.amount, currency: row.currency, status: 'Procesado', bookingId: row.bookingId })), ...prev.transactions] }
      })
      return { transferred: ids.length, status: 'Procesado', simulated: true }
    }
    if (name === BELO_TOOLS.refundPayment) {
      const bookingId = String(args.bookingId ?? '')
      update(prev => {
        const booking = prev.bookings.find(row => row.id === bookingId)
        if (!booking) return prev
        const fee = feeFor(booking.amount)
        const suppliersAlreadyPaid = prev.supplierPayments.some(row => row.bookingId === bookingId && row.status === 'Pagada')
        const pack = prev.packages.find(row => row.id === booking.packageId)
        return { ...prev, balances: { ...prev.balances, [booking.currency]: prev.balances[booking.currency] - refundNet(booking.amount) },
          bookings: prev.bookings.map(row => row.id === bookingId ? { ...row, payment: 'Reembolsado', status: 'Cancelada', history: [...row.history, 'Reembolso aprobado por el agente'] } : row),
          packages: pack ? prev.packages.map(row => row.id === pack.id ? { ...row, seatsLeft: releaseSeats(row.seatsLeft, booking.pax, row.paxTotal) } : row) : prev.packages,
          supplierPayments: prev.supplierPayments.map(row => row.bookingId === bookingId && row.status === 'Pendiente' ? { ...row, status: 'Cancelada' } : row),
          transactions: [{ id: newId('tx'), date: new Date().toISOString().slice(0, 10), kind: 'Reembolso', detail: booking.ref, amount: -(booking.amount - fee), currency: booking.currency, status: 'Procesado', bookingId }, ...prev.transactions],
          notices: [{ id: newId('notice'), title: 'Reembolso procesado', detail: `${booking.ref}${suppliersAlreadyPaid ? ' · Hay pagos a proveedores ya ejecutados' : ''}`, time: 'Ahora', read: false }, ...prev.notices] }
      })
      return { status: 'Reembolso simulado', feeRetained: feeFor(state.bookings.find(row => row.id === bookingId)?.amount ?? 0), simulated: true }
    }
    return { status: 'Simulado' }
  }

  const login = (role: Role) => { sessionStorage.setItem('piluso-demo-role', role); update(prev => ({ ...prev, role })); sessionStorage.setItem('piluso-demo-session', 'active'); setLoggedIn(true) }
  const logout = () => { sessionStorage.removeItem('piluso-demo-session'); sessionStorage.removeItem('piluso-demo-role'); setLoggedIn(false) }
  const resetDemo = () => { if (!window.confirm('¿Reiniciar todos los datos de demostración?')) return; setState(createInitialState()); setPage('overview'); setToast('Datos de demo reiniciados') }
  const title = nav.find(item => item.id === page)?.label ?? 'Overview'
  const unread = state.notices.filter(item => !item.read).length

  if (!loggedIn) return <Welcome onLogin={login} />
  if (state.role === 'traveler') return <Traveler state={state} update={update} callBelo={callBelo} notify={notify} onExit={() => login('owner')} toast={toast} setToast={setToast} />

  return <div className="app-shell">
    <aside className={`sidebar ${mobileNav ? 'sidebar-open' : ''}`}>
      <div className="sidebar-head"><Logo /><button className="icon-button sidebar-close" onClick={() => setMobileNav(false)} aria-label="Cerrar menú"><X size={18} /></button></div>
      <button className="agency-switch" onClick={() => setToast('Estudio Nómade · Cuenta de demostración')}><span className="agency-avatar">EN</span><span className="agency-text"><b>{state.agencyName}</b><small>Cuenta de demo</small></span><ChevronDown size={15} /></button>
      <div className="nav-caption">ESPACIO DE TRABAJO</div>
      <nav className="main-nav">{nav.map(item => <button key={item.id} className={`nav-item ${page === item.id ? 'active' : ''}`} onClick={() => { setPage(item.id); setMobileNav(false) }}><item.icon size={18} strokeWidth={1.8} /><span>{item.label}</span>{item.id === 'conversations' && <span className="nav-count">2</span>}</button>)}</nav>
      <div className="sidebar-spacer" />
      <div className="sidebar-plan"><span className="plan-icon"><Sparkles size={16} /></span><b>Un viaje empieza acá</b><p>Operaciones simples para experiencias memorables.</p><button onClick={() => setAssistantOpen(true)}>Conocer a Pili <ArrowRight size={14} /></button></div>
      <div className="sidebar-user"><span className="user-avatar">{state.role === 'owner' ? 'SM' : 'NV'}</span><span><b>{state.role === 'owner' ? 'Sofía Méndez' : 'Nicolás Vidal'}</b><small>{state.role === 'owner' ? 'Titular de agencia' : 'Agente de viajes'}</small></span><button className="icon-button" onClick={logout} aria-label="Salir"><LogOut size={16} /></button></div>
    </aside>
    {mobileNav && <button className="scrim" onClick={() => setMobileNav(false)} aria-label="Cerrar menú" />}
    <main className="main-area">
      <header className="topbar"><button className="icon-button mobile-menu" onClick={() => setMobileNav(true)} aria-label="Abrir menú"><Menu size={20} /></button><div className="breadcrumbs"><span>Estudio Nómade</span><ChevronRight size={14} /><b>{title}</b></div><div className="top-actions"><span className="demo-pill"><span /> MODO DEMO</span><button className="icon-button notification-button" onClick={() => { setNoticeOpen(!noticeOpen); setNotificationsSeen(true); update(prev => ({ ...prev, notices: prev.notices.map(item => ({ ...item, read: true })) })) }} aria-label="Notificaciones"><Bell size={19} />{unread > 0 && !notificationsSeen && <i />}</button><button className="top-profile" onClick={() => setToast('Sesión de demostración activa')}><span className="user-avatar small-avatar">{state.role === 'owner' ? 'SM' : 'NV'}</span><ChevronDown size={14} /></button></div></header>
      {noticeOpen && <div className="notice-popover"><div className="popover-head"><b>Notificaciones</b><button className="text-button" onClick={() => setNoticeOpen(false)}>Cerrar</button></div>{state.notices.slice(0, 5).map(item => <div className="notice-row" key={item.id}><span className="notice-dot" /><div><b>{item.title}</b><p>{item.detail}</p><small>{item.time}</small></div></div>)}</div>}
      <div className="page-content">
        {page === 'overview' && <Overview state={state} navigate={setPage} openBooking={setSelectedBooking} openConversation={() => setPage('conversations')} />}
        {page === 'packages' && <Packages state={state} onCreate={() => { setEditingPackage(null); setModal('package') }} onEdit={item => { setEditingPackage(item); setModal('package') }} onPreview={setPreviewPackage} notify={setToast} update={update} />}
        {page === 'bookings' && <Bookings state={state} search={search} setSearch={setSearch} openBooking={id => setSelectedBooking(id)} openCustomer={setCustomerOpen} />}
        {page === 'conversations' && <Conversations state={state} update={update} notify={setToast} openCustomer={setCustomerOpen} />}
        {page === 'payments' && <Payments state={state} tab={paymentTab} setTab={setPaymentTab} callBelo={callBelo} notify={setToast} update={update} />}
        {page === 'settings' && <SettingsPage state={state} update={update} reset={resetDemo} notify={setToast} />}
      </div>
    </main>
    <button className={`pili-fab ${assistantOpen ? 'pili-fab-open' : ''}`} onClick={() => setAssistantOpen(!assistantOpen)} aria-label="Abrir asistente Pili"><span className="pili-mark"><Sparkles size={18} /></span><span>{assistantOpen ? 'Cerrar Pili' : 'Pili'}</span></button>
    {assistantOpen && <PiliPanel state={state} page={page} close={() => setAssistantOpen(false)} notify={setToast} />}
    {selectedBooking && <BookingDrawer state={state} bookingId={selectedBooking} close={() => setSelectedBooking(null)} update={update} callBelo={callBelo} notify={setToast} onConversation={() => { setPage('conversations'); setSelectedBooking(null) }} />}
    {customerOpen && <CustomerDrawer state={state} customerId={customerOpen} close={() => setCustomerOpen(null)} openBooking={setSelectedBooking} />}
    {modal === 'package' && <PackageModal item={editingPackage} close={() => setModal(null)} save={item => { update(prev => ({ ...prev, packages: editingPackage ? prev.packages.map(row => row.id === item.id ? item : row) : [item, ...prev.packages] })); setModal(null); setToast(editingPackage ? 'Paquete actualizado' : 'Paquete creado') }} />}
    {previewPackage && <PackagePreviewModal item={previewPackage} close={() => setPreviewPackage(null)} />}
    {toast && <div className="toast"><Check size={16} />{toast}</div>}
  </div>
}

function Welcome({ onLogin }: { onLogin: (role: Role) => void }) {
  const [role, setRole] = useState<Role>('owner')
  return <div className="welcome-page"><div className="welcome-top"><Logo /><span>OPERACIONES DE VIAJE, EN EQUIPO</span></div><div className="welcome-grid"><section className="welcome-copy"><p className="eyebrow"><span /> UNA NUEVA FORMA DE VIAJAR</p><h1>Todo el viaje,<br /><em>en buenas manos.</em></h1><p className="welcome-desc">Una plataforma para cuidar cada detalle: desde la primera consulta hasta el regreso a casa.</p><div className="welcome-points"><span><Check size={15} /> Conversaciones que avanzan</span><span><Check size={15} /> Cobros simples y claros</span><span><Check size={15} /> Cada viaje, bien acompañado</span></div><button className="welcome-cta" onClick={() => onLogin(role)}>Entrar a la demo <ArrowRight size={17} /></button><small className="welcome-note">Sin contraseña · Datos de demostración</small></section><section className="welcome-art" aria-label="Paisaje patagónico ilustrado"><div className="sun" /><div className="art-label"><span>01 — 04</span><b>Un lugar para<br />llegar más lejos.</b><small>EL CALAFATE · PATAGONIA</small></div><svg className="landscape" viewBox="0 0 720 570" preserveAspectRatio="xMidYMid slice" aria-hidden="true"><path d="M0 310 112 240 172 274 281 115 350 220 427 88 518 240 587 160 720 286V570H0Z" fill="#94a397"/><path d="m250 180 31-65 39 60-31-15-15 20-10-14Z M394 145l33-57 35 61-30-17-17 18Z" fill="#f5f1e6"/><path d="M0 340 138 281l105 39 130-100 127 86 91-51 129 63V570H0Z" fill="#45685b"/><path d="M0 403q112-47 215 4t220-7 285 4v166H0Z" fill="#244e43"/><path d="M0 462q146-40 278 2t240-6 202 0v112H0Z" fill="#183d35"/></svg></section></div><div className="welcome-login"><span>Entrar como</span>{([{ key: 'owner' as Role, label: 'Titular' }, { key: 'agent' as Role, label: 'Agente' }, { key: 'traveler' as Role, label: 'Viajero' }]).map(item => <button key={item.key} onClick={() => setRole(item.key)} className={role === item.key ? 'chosen' : ''}>{item.label}</button>)}</div><footer><span>© 2026 Piluso</span><span>Un prototipo de Estudio Nómade</span><span>Experiencias con sentido</span></footer></div>
}

function PageHeading({ eyebrow, title, subtitle, action }: { eyebrow: string; title: string; subtitle: string; action?: ReactNode }) {
  return <div className="page-heading"><div><p className="eyebrow">{eyebrow}</p><h1>{title}</h1><p className="page-subtitle">{subtitle}</p></div>{action && <div className="heading-action">{action}</div>}</div>
}
function Button({ children, onClick, variant = 'primary', icon, type = 'button', disabled = false }: { children: ReactNode; onClick?: () => void; variant?: 'primary' | 'secondary' | 'ghost' | 'dark'; icon?: ReactNode; type?: 'button' | 'submit'; disabled?: boolean }) {
  return <button className={`button button-${variant}`} onClick={onClick} type={type} disabled={disabled}>{icon}{children}</button>
}
function Status({ children }: { children: string }) {
  const cls = /Aprobado|Confirmada|Pagada|Resuelta|Procesado/i.test(children) ? 'good' : /Cancel|Rechaz|Reembols|Error/i.test(children) ? 'bad' : 'pending'
  return <span className={`status status-${cls}`}><i />{children}</span>
}
function Avatar({ initials, tone = 'sage' }: { initials: string; tone?: string }) { return <span className={`avatar avatar-${tone}`}>{initials}</span> }
function EmptyState({ title, description }: { title: string; description: string }) { return <div className="empty-state"><span><Package size={20} /></span><b>{title}</b><p>{description}</p></div> }

function Overview({ state, navigate, openBooking, openConversation }: { state: AppState; navigate: (page: Page) => void; openBooking: (id: string) => void; openConversation: () => void }) {
  const [period, setPeriod] = useState('30')
  const cutoff = new Date()
  cutoff.setDate(cutoff.getDate() - Number(period))
  const recentBookings = state.bookings.filter(item => new Date(`${item.createdAt}T12:00:00`) >= cutoff)
  const approved = recentBookings.filter(item => item.payment === 'Aprobado')
  const pending = recentBookings.filter(item => item.payment === 'Pendiente')
  const revenueArs = approved.filter(item => item.currency === 'ARS').reduce((sum, item) => sum + item.amount, 0)
  const revenueUsd = approved.filter(item => item.currency === 'USD').reduce((sum, item) => sum + item.amount, 0)
  const marginArs = approved.filter(item => item.currency === 'ARS').reduce((sum, item) => sum + agencyNet(item.amount, item.pax * (state.packages.find(pkg => pkg.id === item.packageId)?.costs ?? 0)), 0)
  const upcoming = state.bookings.filter(item => item.status === 'Confirmada' || item.status === 'Solicitada')
  const pendingSupplierCount = state.supplierPayments.filter(item => item.status === 'Pendiente').length
  const monthlyRevenue = Array.from({ length: 12 }, (_, index) => approved.filter(item => new Date(`${item.createdAt}T12:00:00`).getMonth() === index).reduce((sum, item) => sum + (item.currency === 'ARS' ? item.amount : convertCurrency(item.amount, 'USD', 'ARS')), 0))
  const maxMonthlyRevenue = Math.max(1, ...monthlyRevenue)
  const chartHeights = monthlyRevenue.map(amount => amount ? Math.max(18, Math.round(amount / maxMonthlyRevenue * 100)) : 8)
  return <>
    <div className="overview-greeting"><div><p className="eyebrow">SÁBADO, 7 DE NOVIEMBRE DE 2026</p><h1>Buen día, Sofía <span>✳</span></h1><p>Acá tenés un panorama de lo que pasa en tu agencia.</p></div><label className="period-filter"><CalendarDays size={15} /><select value={period} onChange={event => setPeriod(event.target.value)} aria-label="Período del resumen"><option value="30">Últimos 30 días</option><option value="90">Últimos 90 días</option><option value="365">Este año</option></select><ChevronDown size={14} /></label></div>
    <section className="overview-hero"><div className="hero-topline"><span><span className="live-dot" /> TU AGENCIA EN MOVIMIENTO</span><span>ESTUDIO NÓMADE · DEMO</span></div><div className="hero-columns"><div className="hero-intro"><p>Una operación más simple.</p><h2>Más tiempo para<br /><em>lo extraordinario.</em></h2><span>El trabajo diario, en un solo lugar.</span></div><div className="hero-art"><div className="hero-sun" /><div className="hero-mountain m1" /><div className="hero-mountain m2" /><div className="hero-mountain m3" /><span className="hero-art-caption">PATAGONIA, ARGENTINA</span></div></div><div className="hero-bottom"><span><ShieldCheck size={15} /> Todo está al día</span><button onClick={openConversation}>Ver conversaciones <ArrowRight size={15} /></button></div></section>
    <div className="metric-grid"><Metric icon={<BriefcaseBusiness />} label="Reservas activas" value={String(state.bookings.filter(item => item.status !== 'Cancelada').length).padStart(2, '0')} detail="En todos tus viajes" /><Metric icon={<ArrowDownLeft />} label="Cobrado este mes" value={money(revenueArs, 'ARS')} detail={revenueUsd ? `+ ${money(revenueUsd, 'USD')}` : 'Pagos confirmados'} tone="green" /><Metric icon={<Clock3 />} label="Por cobrar" value={String(pending.length).padStart(2, '0')} detail="Reservas pendientes" tone="sand" /><Metric icon={<CircleDollarSign />} label="Margen estimado" value={money(marginArs, 'ARS')} detail="Luego de costos y comisión" /><Metric icon={<Wallet />} label="Saldo Belo" value={money(state.balances.ARS, 'ARS')} detail={`${money(state.balances.USD, 'USD')} disponible en USD`} tone="green" /><Metric icon={<Banknote />} label="Pagos a proveedores" value={String(pendingSupplierCount).padStart(2, '0')} detail="Pendientes de ejecutar" tone="sand" /></div>
    <div className="content-grid overview-lower"><section className="panel arrivals-panel"><PanelHead title="Próximas salidas" subtitle="Viajes que ya están en el horizonte" action={<button className="text-button" onClick={() => navigate('bookings')}>Ver todas <ArrowRight size={14} /></button>} /><div className="departure-list">{upcoming.slice(0, 4).map((booking, index) => { const customer = state.customers.find(item => item.id === booking.customerId); const pkg = state.packages.find(item => item.id === booking.packageId); return <button className="departure-row" key={booking.id} onClick={() => openBooking(booking.id)}><span className={`departure-date date-${index}`}><small>{index === 0 ? 'DIC' : index === 1 ? 'ENE' : 'MAR'}</small><b>{String(12 + index * 4).padStart(2, '0')}</b></span><div className="departure-info"><b>{pkg?.name}</b><span>{customer?.name} · {booking.pax} viajeros</span></div><span className="departure-when">{booking.payment === 'Aprobado' ? 'Confirmado' : 'Por cobrar'}</span><ChevronRight size={16} /></button> })}</div><button className="panel-footer-link" onClick={() => navigate('packages')}><Plus size={15} /> Crear un paquete nuevo</button></section>
      <section className="panel activity-panel"><PanelHead title="Para tener en cuenta" subtitle="Lo que necesita tu atención" action={<button className="text-button" onClick={() => navigate('conversations')}>Ver inbox <ArrowRight size={14} /></button>} />{state.notices.slice(0, 3).map((notice, index) => <div className="activity-row" key={notice.id}><span className={`activity-icon activity-${index}`}><MessageCircle size={16} /></span><div><b>{notice.title}</b><p>{notice.detail}</p><small>{notice.time}</small></div><ArrowUpRight size={15} /></div>)}<div className="insight-card"><span className="insight-spark"><Sparkles size={16} /></span><div><b>Una sugerencia de Pili</b><p>Tenés {pending.length} reserva{pending.length === 1 ? '' : 's'} por cobrar. Un recordatorio amable puede ayudar a cerrar el próximo viaje.</p><button onClick={() => navigate('conversations')}>Revisar conversaciones <ArrowRight size={14} /></button></div></div></section></div>
    <section className="panel chart-panel"><PanelHead title="Así viene el mes" subtitle="Cobros y margen de tus reservas confirmadas" action={<button className="text-button" onClick={() => navigate('payments')}>Ver movimientos <ArrowRight size={14} /></button>} /><div className="chart-legend"><span><i className="legend-revenue" /> Ingresos</span><span><i className="legend-margin" /> Margen</span><b>{money(revenueArs, 'ARS')} <small>cobrado</small></b></div><div className="chart-bars" aria-label="Gráfico ilustrativo de actividad mensual">{chartHeights.map((height, index) => <div className="chart-bar-group" key={index}><span className="bar-revenue" style={{ height: `${height}%` }} /><span className="bar-margin" style={{ height: `${Math.round(height * 0.45)}%` }} /></div>)}</div><div className="chart-months"><span>ENE</span><span>FEB</span><span>MAR</span><span>ABR</span><span>MAY</span><span>JUN</span><span>JUL</span><span>AGO</span><span>SEP</span><span>OCT</span><span>NOV</span><span>DIC</span></div><p className="demo-caption">Valores de demostración · Los gráficos responden a los datos locales de la demo.</p></section>
  </>
}
function Metric({ icon, label, value, detail, tone = '' }: { icon: ReactNode; label: string; value: string; detail: string; tone?: string }) { return <div className="metric-card"><div className="metric-top"><span className={`metric-icon ${tone}`}>{icon}</span><span className="metric-label">{label}</span><MoreHorizontal size={17} /></div><b className="metric-value">{value}</b><small>{detail}</small></div> }
function PanelHead({ title, subtitle, action }: { title: string; subtitle: string; action?: ReactNode }) { return <div className="panel-head"><div><h2>{title}</h2><p>{subtitle}</p></div>{action}</div> }

function Packages({ state, onCreate, onEdit, onPreview, notify, update }: { state: AppState; onCreate: () => void; onEdit: (item: PackageItem) => void; onPreview: (item: PackageItem) => void; notify: (message: string) => void; update: (fn: (prev: AppState) => AppState) => void }) {
  const [filter, setFilter] = useState('Todos')
  const visible = state.packages.filter(item => !item.archived && (filter === 'Todos' || (filter === 'Publicados' ? item.published : !item.published)))
  return <><PageHeading eyebrow="TU COLECCIÓN" title="Paquetes" subtitle="Diseñá viajes memorables y compartilos con tus viajeros." action={<Button icon={<Plus size={16} />} onClick={onCreate}>Nuevo paquete</Button>} />
    <div className="toolbar"><div className="tabs">{['Todos', 'Publicados', 'Borradores'].map(item => <button onClick={() => setFilter(item)} className={filter === item ? 'selected' : ''} key={item}>{item}</button>)}</div><span className="toolbar-count">{visible.length} paquetes</span><button className="icon-button" aria-label="Filtrar" onClick={() => notify('Mostrando paquetes según el filtro seleccionado')}><Filter size={17} /></button></div>
    <div className="package-grid">{visible.map(item => <article className="package-card" key={item.id}><div className={`package-art art-${item.theme}`}><span className="package-tag">{item.type.split(' · ')[0]}</span><button className="package-more" onClick={() => onEdit(item)} aria-label={`Editar ${item.name}`}><MoreHorizontal size={19} /></button><div className="package-landscape"><i /><b /><em /></div><span className="package-destination"><MapPin size={14} />{item.destination}</span></div><div className="package-card-body"><div className="package-title-line"><h2>{item.name}</h2><Status>{item.published ? 'Publicado' : 'Borrador'}</Status></div><p>{item.description}</p><div className="package-meta"><span><CalendarDays size={14} />{item.dates}</span><span><Users size={14} />{item.seatsLeft} lugares</span></div><div className="package-card-bottom"><span>Desde <b>{money(item.priceDouble, item.currency)}</b><small>por persona · base doble</small></span><button className="text-button" onClick={() => onEdit(item)}>Editar <ArrowRight size={14} /></button></div><div className="package-card-controls"><button onClick={() => { navigator.clipboard?.writeText(`${location.origin}/#viajero/${item.id}`); notify('Enlace del paquete copiado') }}><Link2 size={14} /> Compartir</button><button onClick={() => onPreview(item)}><Eye size={14} />Vista previa</button><button onClick={() => update(prev => ({ ...prev, packages: prev.packages.map(row => row.id === item.id ? { ...row, published: !row.published } : row) }))}><Eye size={14} />{item.published ? 'Despublicar' : 'Publicar'}</button><button onClick={() => update(prev => ({ ...prev, packages: prev.packages.map(row => row.id === item.id ? { ...row, id: newId('pkg'), name: `${row.name} · copia`, published: false, seatsLeft: row.paxTotal } : row) }))}><Copy size={14} />Duplicar</button><button onClick={() => update(prev => ({ ...prev, packages: prev.packages.map(row => row.id === item.id ? { ...row, archived: true } : row) }))}><X size={14} />Archivar</button></div></div></article>)}</div>
    {!visible.length && <EmptyState title="Todavía no hay paquetes acá" description="Creá un paquete para empezar a compartir viajes con tus clientes." />}
  </>
}

function Bookings({ state, search, setSearch, openBooking, openCustomer }: { state: AppState; search: string; setSearch: (value: string) => void; openBooking: (id: string) => void; openCustomer: (id: string) => void }) {
  const [status, setStatus] = useState('Todas')
  const filtered = state.bookings.filter(item => { const customer = state.customers.find(c => c.id === item.customerId)?.name ?? ''; const pkg = state.packages.find(p => p.id === item.packageId)?.name ?? ''; return `${item.ref} ${customer} ${pkg}`.toLowerCase().includes(search.toLowerCase()) && (status === 'Todas' || item.payment === status) })
  return <><PageHeading eyebrow="SEGUIMIENTO" title="Reservas" subtitle="Cada reserva, desde la primera consulta hasta el regreso." /><div className="toolbar booking-toolbar"><div className="search-field"><Search size={16} /><input placeholder="Buscar por viajero, paquete o código" value={search} onChange={e => setSearch(e.target.value)} /></div><select value={status} onChange={e => setStatus(e.target.value)}><option>Todas</option><option>Pendiente</option><option>Aprobado</option><option>Rechazado</option></select><button className="button button-secondary" onClick={() => setStatus('Todas')}><Filter size={15} /> Filtros</button></div><section className="panel table-panel"><div className="table-scroll"><table><thead><tr><th>RESERVA</th><th>VIAJERO</th><th>PAQUETE</th><th>FECHA</th><th>IMPORTE</th><th>PAGO</th><th /></tr></thead><tbody>{filtered.map(item => { const customer = state.customers.find(c => c.id === item.customerId); const pkg = state.packages.find(p => p.id === item.packageId); return <tr key={item.id}><td><button className="table-ref" onClick={() => openBooking(item.id)}>{item.ref}</button></td><td><button className="person-cell" onClick={() => customer && openCustomer(customer.id)}><Avatar initials={customer?.initials ?? '??'} />{customer?.name}</button></td><td>{pkg?.name}</td><td>{pkg?.dates.split(' ')[0]} {pkg?.dates.split(' ')[1]}</td><td className="amount-cell">{money(item.amount, item.currency)}<small>{item.pax} pasajeros</small></td><td><Status>{item.payment}</Status></td><td><button className="icon-button" onClick={() => openBooking(item.id)} aria-label="Ver reserva"><ArrowRight size={16} /></button></td></tr> })}</tbody></table></div>{!filtered.length && <EmptyState title="No encontramos reservas" description="Probá con otro término o cambiá el filtro de estado." />}<div className="table-footer"><span>Mostrando {filtered.length} de {state.bookings.length} reservas</span><div><button className="icon-button" disabled><ChevronLeft size={16} /></button><button className="page-number">1</button><button className="icon-button" disabled><ChevronRight size={16} /></button></div></div></section></>
}

function Conversations({ state, update, notify, openCustomer }: { state: AppState; update: (fn: (prev: AppState) => AppState) => void; notify: (message: string) => void; openCustomer: (id: string) => void }) {
  const [selected, setSelected] = useState(state.conversations[0]?.id ?? '')
  const [message, setMessage] = useState('')
  const [filter, setFilter] = useState('Todas')
  const conversation = state.conversations.find(item => item.id === selected)
  const customer = conversation ? state.customers.find(item => item.id === conversation.customerId) : undefined
  const pkg = conversation?.packageId ? state.packages.find(item => item.id === conversation.packageId) : undefined
  const filtered = state.conversations.filter(item => filter === 'Todas' || item.channel === filter)
  const send = (event: FormEvent) => { event.preventDefault(); if (!message.trim() || !conversation) return; const nextMessage = { id: newId('msg'), from: 'agent' as const, text: message.trim(), time: timeNow() }; update(prev => ({ ...prev, conversations: prev.conversations.map(row => row.id === conversation.id ? { ...row, messages: [...row.messages, nextMessage], updated: 'Ahora' } : row) })); setMessage(''); notify('Mensaje enviado en la demo') }
  const handoff = (mode: Conversation['mode']) => { if (!conversation) return; update(prev => ({ ...prev, conversations: prev.conversations.map(row => row.id === conversation.id ? { ...row, mode } : row) })); notify(mode === 'Agente' ? 'Tomaste la conversación. Pili queda en pausa.' : 'Pili vuelve a acompañar esta conversación.') }
  const draft = () => { setMessage(`¡Hola ${customer?.name.split(' ')[0] ?? ''}! Gracias por escribirnos. Ya revisé los detalles de ${pkg?.name ?? 'tu viaje'} y con gusto te acompaño para que tengas toda la información. ¿Querés que te comparta el próximo paso?`); notify('Borrador de Pili listo para revisar') }
  const simulateResponse = () => { if (!conversation) return; update(prev => ({ ...prev, conversations: prev.conversations.map(row => row.id === conversation.id ? { ...row, updated: 'Ahora', messages: [...row.messages, { id: newId('msg'), from: 'customer', text: '¡Gracias! Me interesa conocer las opciones y el próximo paso.', time: timeNow() }] } : row) })); notify('Respuesta de viajero agregada a la demo') }
  return <><PageHeading eyebrow="CERCA DE TUS VIAJEROS" title="Conversaciones" subtitle="Cada buen viaje empieza con una buena charla." action={<Button variant="secondary" icon={<Headphones size={16} />} onClick={() => notify('Canales web y WhatsApp en modo demo')}>Canales conectados</Button>} /><div className="inbox-layout"><aside className="inbox-list"><div className="inbox-list-head"><div className="search-field"><Search size={15} /><input placeholder="Buscar conversación" /></div><div className="tabs mini-tabs">{['Todas', 'WhatsApp', 'Web'].map(item => <button key={item} onClick={() => setFilter(item)} className={filter === item ? 'selected' : ''}>{item}</button>)}</div></div>{filtered.map(item => { const person = state.customers.find(row => row.id === item.customerId); const last = item.messages[item.messages.length - 1]; return <button key={item.id} className={`conversation-preview ${selected === item.id ? 'active' : ''}`} onClick={() => setSelected(item.id)}><Avatar initials={person?.initials ?? '??'} tone={item.channel === 'WhatsApp' ? 'green' : 'sand'} /><span className="conversation-preview-text"><span><b>{person?.name}</b><small>{item.updated}</small></span><span className="preview-message">{last?.text}</span><small className="channel-label">{item.channel} · {item.mode === 'Pili' ? 'Atiende Pili' : 'Atiende agente'}</small></span></button>})}</aside><section className="conversation-pane">{conversation && customer ? <><div className="conversation-head"><div className="conversation-contact"><Avatar initials={customer.initials} /><div><b>{customer.name}</b><span>{conversation.channel} · {customer.phone}</span></div><button className="text-button" onClick={() => openCustomer(customer.id)}>Ver ficha</button></div><div className="conversation-controls"><span className={`ownership ${conversation.mode === 'Pili' ? 'ownership-pili' : ''}`}><i />{conversation.mode === 'Pili' ? 'Pili responde' : 'Atención humana'}</span><select value={conversation.assigned} onChange={e => update(prev => ({ ...prev, conversations: prev.conversations.map(row => row.id === conversation.id ? { ...row, assigned: e.target.value } : row) }))}><option>Sofía Méndez</option><option>Nicolás Vidal</option></select><button className="icon-button" onClick={() => update(prev => ({ ...prev, conversations: prev.conversations.map(row => row.id === conversation.id ? { ...row, status: row.status === 'Abierta' ? 'Resuelta' : 'Abierta' } : row) }))} aria-label="Resolver conversación"><CheckCheck size={17} /></button></div></div><div className="conversation-context"><span><Package size={15} />{pkg?.name ?? 'Sin paquete asociado'}</span>{pkg && <span>{pkg.destination}</span>}<button onClick={() => notify('Se preparó el paquete para compartir en la conversación')}><Link2 size={14} /> Sugerir paquete</button></div><div className="messages-area"><div className="day-divider"><span>HOY · 7 DE NOVIEMBRE</span></div>{conversation.messages.map(item => <div className={`message-row message-${item.from}`} key={item.id}><div className="message-bubble">{item.from === 'pili' && <small><Sparkles size={12} /> PILI</small>}{item.text}<time>{item.time}</time></div></div>)}</div><div className="handoff-bar"><span>{conversation.mode === 'Pili' ? 'Pili está acompañando esta charla.' : 'La conversación está asignada a un agente.'}</span><button className="text-button" onClick={() => handoff(conversation.mode === 'Pili' ? 'Agente' : 'Pili')}>{conversation.mode === 'Pili' ? 'Tomar conversación' : 'Devolver a Pili'} <ArrowRight size={14} /></button></div><form className="message-composer" onSubmit={send}><button type="button" className="composer-ai" onClick={draft}><Sparkles size={15} /> Redactar con Pili</button><button type="button" className="composer-ai" onClick={simulateResponse}><MessageCircle size={14} /> Simular respuesta</button><div className="composer-input"><input value={message} onChange={e => setMessage(e.target.value)} placeholder="Escribí un mensaje…" /><button className="send-button" aria-label="Enviar mensaje"><Send size={16} /></button></div><small>Envío simulado · No se contacta a nadie</small></form></> : <EmptyState title="Elegí una conversación" description="Seleccioná una charla para ver su historial." />}</section><aside className="inbox-side"><div className="customer-profile"><Avatar initials={customer?.initials ?? '??'} tone="sand" /><h3>{customer?.name ?? 'Viajero'}</h3><p>Viajero desde 2025</p><button className="text-button" onClick={() => customer && openCustomer(customer.id)}>Ver ficha completa <ArrowRight size={14} /></button></div><div className="side-divider" /><div className="side-detail"><small>PAQUETE DE INTERÃ‰S</small>{pkg ? <><b>{pkg.name}</b><span>{pkg.destination}</span><span>{pkg.dates}</span><Button variant="secondary" onClick={() => notify('Enlace al paquete compartido en la conversación')} icon={<Link2 size={14} />}>Compartir paquete</Button></> : <span>Aún no hay paquete vinculado</span>}</div><div className="side-divider" /><div className="side-detail"><small>ASISTENTE</small><div className="pili-mini"><span className="pili-mark"><Sparkles size={14} /></span><div><b>Pili</b><span>Asistencia simulada</span></div></div><button className="text-button" onClick={draft}>Preparar respuesta <ArrowRight size={14} /></button></div></aside></div></>
}

function Payments({ state, tab, setTab, callBelo, notify, update }: { state: AppState; tab: string; setTab: (value: string) => void; callBelo: (tool: string, args: Record<string, unknown>) => Promise<unknown>; notify: (message: string) => void; update: (fn: (prev: AppState) => AppState) => void }) {
  const [selected, setSelected] = useState<string[]>([])
  const [converting, setConverting] = useState(false)
  const tabs = ['Balance y movimientos', 'Pagos a proveedores', 'Directorio']
  const pending = state.supplierPayments.filter(item => item.status === 'Pendiente')
  const execute = async () => {
    if (!selected.length) return notify('Seleccioná al menos un pago pendiente')
    const rows = pending.filter(row => selected.includes(row.id))
    const invalid = rows.find(row => !row.concept.trim() || row.amount <= 0 || (row.currency === 'ARS' ? !/^\d{22}$/.test(row.destination) : !/^[a-zA-Z0-9._-]{3,}$/.test(row.destination)))
    if (invalid) return notify(invalid.currency === 'ARS' ? 'Revisá el monto y el CBU de 22 dígitos antes de confirmar.' : 'Revisá el monto y el alias Belo antes de confirmar.')
    const needed: Record<Currency, number> = { ARS: 0, USD: 0 }
    rows.forEach(row => { needed[row.currency] += row.amount })
    const short = (['ARS', 'USD'] as Currency[]).find(currency => needed[currency] > state.balances[currency])
    if (short) {
      const other: Currency = short === 'ARS' ? 'USD' : 'ARS'
      if (state.balances[other] > 0 && !converting) return setConverting(true)
      return notify(`Saldo insuficiente en ${short}. Ajustá la selección o el saldo demo.`)
    }
    const arsIds = rows.filter(row => row.currency === 'ARS').map(row => row.id)
    const usdIds = rows.filter(row => row.currency === 'USD').map(row => row.id)
    if (arsIds.length) await callBelo(BELO_TOOLS.sendBankTransfer, { ids: arsIds })
    if (usdIds.length) await callBelo(BELO_TOOLS.sendBeloTransfer, { ids: usdIds })
    setSelected([]); setConverting(false); notify('Pagos a proveedores ejecutados en modo demo')
  }
  const convertToCover = async (currency: Currency) => {
    const other: Currency = currency === 'ARS' ? 'USD' : 'ARS'
    const amount = pending.filter(row => selected.includes(row.id) && row.currency === currency).reduce((sum, row) => sum + row.amount, 0)
    const available = state.balances[other]
    const converted = convertCurrency(available, other, currency)
    if (converted < amount) return notify('La conversión disponible no alcanza para cubrir los pagos seleccionados.')
    await callBelo(BELO_TOOLS.convert, { amount: available, from: other, to: currency })
    updateBalanceDemo(currency, converted)
    setConverting(false); notify(`Conversión demo realizada: ${money(available, other)} â†’ ${money(converted, currency)}`)
  }
  const updateBalanceDemo = (currency: Currency, amount: number) => update(prev => ({ ...prev, balances: { ...prev.balances, [currency]: prev.balances[currency] + amount, [currency === 'ARS' ? 'USD' : 'ARS']: 0 }, transactions: [{ id: newId('tx'), date: new Date().toISOString().slice(0, 10), kind: 'Conversión demo', detail: `Saldo convertido al tipo demo ${fxRateLabel()}`, amount, currency, status: 'Procesado' }, ...prev.transactions] }))
  return <><PageHeading eyebrow="COBROS Y OPERACIÓN" title="Pagos" subtitle="Una mirada clara a los fondos que entran y salen." action={<Button variant="secondary" icon={<ExternalLink size={15} />} onClick={() => callBelo(BELO_TOOLS.getBalance, {})}>Consultar Belo MCP</Button>} /><div className="balance-banner"><div><p>Saldo disponible <span className="demo-caption-inline">DEMO</span></p><div className="balance-values"><span>{money(state.balances.ARS, 'ARS')} <small>ARS</small></span><i /><span>{money(state.balances.USD, 'USD')} <small>USD</small></span></div><small className="fx-note">Cambio de referencia de demo · {fxRateLabel()}</small></div><div className="balance-graphic"><span><Wallet size={22} /></span><i /><b>BELO</b><small>CUENTA SIMULADA</small></div></div><div className="toolbar payment-toolbar"><div className="tabs">{tabs.map(item => <button key={item} className={tab === item ? 'selected' : ''} onClick={() => setTab(item)}>{item}</button>)}</div><span className="toolbar-count">{state.transactions.length} movimientos</span></div>
    {tab === tabs[0] && <section className="panel table-panel"><PanelHead title="Balance y movimientos" subtitle="Cobros, comisiones y transferencias simuladas" action={<Button variant="secondary" onClick={() => callBelo(BELO_TOOLS.getTransferInstructions, {})} icon={<Landmark size={15} />}>Datos de transferencia</Button>} /><div className="table-scroll"><table><thead><tr><th>FECHA</th><th>TIPO</th><th>DETALLE</th><th>IMPORTE</th><th>ESTADO</th></tr></thead><tbody>{state.transactions.map(item => <tr key={item.id}><td>{item.date}</td><td>{item.kind}</td><td>{item.detail}</td><td className={item.amount < 0 ? 'negative amount-cell' : 'positive amount-cell'}>{item.amount > 0 ? '+' : ''}{money(item.amount, item.currency)}</td><td><Status>{item.status}</Status></td></tr>)}</tbody></table></div>{!state.transactions.length && <EmptyState title="Sin movimientos todavía" description="Los cobros simulados aparecerán acá." />}</section>}
    {tab === tabs[1] && <section className="panel table-panel supplier-table-panel"><PanelHead title="Pagos a proveedores" subtitle="Revisá los costos pendientes y confirmá la transferencia en lote." action={<Button onClick={execute} disabled={!selected.length} icon={<Check size={15} />}>Confirmar pagos ({selected.length})</Button>} /><div className="demo-workflow-note"><Sparkles size={16} /><span><b>Flujo de demostración</b> · Revisá los conceptos, importes y destinos antes de ejecutar. No se envía dinero.</span></div><div className="table-scroll"><table><thead><tr><th><input type="checkbox" aria-label="Seleccionar todos" checked={pending.length > 0 && selected.length === pending.length} onChange={e => setSelected(e.target.checked ? pending.map(row => row.id) : [])} /></th><th>PROVEEDOR / CONCEPTO</th><th>RESERVA</th><th>IMPORTE</th><th>DESTINO</th><th>ESTADO</th></tr></thead><tbody>{state.supplierPayments.map(row => { const supplier = state.suppliers.find(item => item.id === row.supplierId); return <tr key={row.id}><td><input type="checkbox" aria-label={`Seleccionar ${row.concept}`} disabled={row.status !== 'Pendiente'} checked={selected.includes(row.id)} onChange={e => setSelected(e.target.checked ? [...selected, row.id] : selected.filter(id => id !== row.id))} /></td><td><b>{supplier?.name}</b><input className="inline-destination" value={row.concept} aria-label="Concepto editable" onChange={e => update(prev => ({ ...prev, supplierPayments: prev.supplierPayments.map(item => item.id === row.id ? { ...item, concept: e.target.value } : item) }))} /></td><td>{state.bookings.find(item => item.id === row.bookingId)?.ref}</td><td><input className="inline-amount" value={row.amount} aria-label="Importe editable" onChange={e => { const value = Number(e.target.value); update(prev => ({ ...prev, supplierPayments: prev.supplierPayments.map(item => item.id === row.id ? { ...item, amount: Number.isFinite(value) ? value : 0 } : item) })) }} /> <small>{row.currency}</small></td><td><input className="inline-destination" value={row.destination} aria-label="Destino editable" onChange={e => update(prev => ({ ...prev, supplierPayments: prev.supplierPayments.map(item => item.id === row.id ? { ...item, destination: e.target.value } : item) }))} /></td><td><Status>{row.status}</Status></td></tr>})}</tbody></table></div>{converting && <div className="conversion-box"><div><b>Saldo insuficiente para esta selección</b><p>Podés convertir el saldo disponible de la otra moneda al tipo de cambio demo de {fxRateLabel()}.</p></div><Button onClick={() => { const currency = pending.find(row => selected.includes(row.id))?.currency ?? 'ARS'; void convertToCover(currency) }} icon={<RotateCcw size={15} />}>Proponer conversión</Button></div>}<div className="table-footer"><span>{pending.length} pagos pendientes · {state.supplierPayments.filter(row => row.status === 'Pagada').length} completados</span><span className="demo-caption">No es una regla de producción</span></div></section>}
    {tab === tabs[2] && <section className="supplier-directory">{state.suppliers.map(supplier => <article className="panel supplier-card" key={supplier.id}><span className={`supplier-symbol ${supplier.currency === 'USD' ? 'supplier-usd' : ''}`}><BriefcaseBusiness size={18} /></span><div><h3>{supplier.name}</h3><p>{supplier.service} · {supplier.destination}</p><small>{supplier.contact}</small></div><span className="currency-chip">{supplier.currency}</span><button className="icon-button" onClick={() => notify(`Contacto copiado: ${supplier.contact}`)} aria-label="Copiar contacto"><Copy size={16} /></button></article>)}</section>}
    <section className="mcp-panel"><div className="mcp-head"><div><span className="mcp-icon"><Bot size={17} /></span><div><b>Belo MCP</b><small>Panel de actividad · simulación local</small></div></div><span className="demo-pill"><span /> SIN CONEXIÓN</span></div>{state.calls.length ? <div className="mcp-calls">{state.calls.slice(0, 4).map(call => <details key={call.id}><summary><span className={`call-status ${call.status}`} /><b>{call.tool}</b><small>{call.at}</small><ChevronDown size={15} /></summary><div className="call-json"><span>REQUEST</span><pre>{JSON.stringify(call.request, null, 2)}</pre><span>RESPONSE · {call.status.toUpperCase()}</span><pre>{JSON.stringify(call.response, null, 2)}</pre></div></details>)}</div> : <p className="mcp-empty">Las operaciones de demo aparecen aquí como llamadas y respuestas JSON. <button className="text-button" onClick={() => callBelo(BELO_TOOLS.getBalance, {})}>Probar get_balance <ArrowRight size={13} /></button></p>}</section>
  </>
}

function SettingsPage({ state, update, reset, notify }: { state: AppState; update: (fn: (prev: AppState) => AppState) => void; reset: () => void; notify: (message: string) => void }) {
  const [section, setSection] = useState('Agencia')
  const [agency, setAgency] = useState(state.agencyName)
  const [country, setCountry] = useState(state.agencyCountry)
  const [email, setEmail] = useState(state.agencyEmail)
  return <><PageHeading eyebrow="TU ESPACIO" title="Configuración" subtitle="Los detalles que hacen que tu agencia se sienta como tuya." /><div className="settings-layout"><aside className="settings-nav">{['Agencia', 'Equipo', 'Notificaciones', 'Cuenta Belo', 'Datos demo'].map(item => <button key={item} onClick={() => setSection(item)} className={section === item ? 'selected' : ''}>{item}</button>)}</aside><section className="panel settings-panel">{section === 'Agencia' && <><h2>Perfil de agencia</h2><p>Esta información acompaña tus viajes y comunicaciones.</p><label>Nombre de la agencia<input value={agency} onChange={e => setAgency(e.target.value)} /></label><label>País<select value={country} onChange={e => setCountry(e.target.value)}><option>Argentina</option><option>Chile</option><option>Uruguay</option><option>Brasil</option></select></label><label>Correo de contacto<input value={email} onChange={e => setEmail(e.target.value)} type="email" /></label><Button onClick={() => { if (!agency.trim() || !email.includes('@') || !email.includes('.')) return notify('Ingresá un nombre y un correo de contacto válido.'); update(prev => ({ ...prev, agencyName: agency, agencyCountry: country, agencyEmail: email })); notify('Perfil de agencia guardado') }}>Guardar cambios</Button></>}{section === 'Equipo' && <><h2>Personas que hacen equipo</h2><p>Accesos y roles disponibles en esta cuenta demo.</p>{['Sofía Méndez · Titular de agencia', 'Nicolás Vidal · Agente de viajes'].map((item, index) => <div className="team-row" key={item}><Avatar initials={index ? 'NV' : 'SM'} /><span><b>{item.split(' · ')[0]}</b><small>{item.split(' · ')[1]}</small></span><Status>Activo</Status></div>)}<Button variant="secondary" onClick={() => notify('En una versión real, desde acá invitarías a una persona del equipo.')} icon={<Plus size={15} />}>Invitar persona</Button></>}{section === 'Notificaciones' && <><h2>Preferencias de notificación</h2><p>Elegí qué novedades querés tener cerca.</p>{['Nuevas consultas de viajeros', 'Paquetes confirmados', 'Pagos aprobados o rechazados', 'Solicitudes de cancelación', 'Resumen semanal'].map((item, index) => <label className="toggle-row" key={item}><span><b>{item}</b><small>En la aplicación y en WhatsApp simulado</small></span><input type="checkbox" defaultChecked={index < 4} /></label>)}<Button onClick={() => notify('Preferencias guardadas')}>Guardar preferencias</Button></>}{section === 'Cuenta Belo' && <><h2>Cuenta Belo simulada</h2><p>Esta cuenta no está conectada a una billetera real.</p><div className="settings-balance"><span><Wallet size={18} /> Saldo disponible</span><b>{money(state.balances.ARS, 'ARS')} · {money(state.balances.USD, 'USD')}</b></div><div className="settings-note"><ShieldCheck size={17} /> Todas las operaciones en esta demo son ficticias. No se procesan pagos reales.</div><Button variant="secondary" onClick={() => notify('Configuración de demo · Belo no está conectado')}>Ver datos de cuenta</Button></>}{section === 'Datos demo' && <><h2>Datos de demostración</h2><p>Los cambios se guardan localmente en este navegador y se sincronizan entre pestañas.</p><div className="settings-note"><RotateCcw size={17} /><span>Reiniciar vuelve a cargar paquetes, conversaciones, reservas y saldos de ejemplo.</span></div><Button variant="dark" onClick={reset} icon={<RotateCcw size={15} />}>Reiniciar datos demo</Button></>}</section></div></>
}

function PackageModal({ item, close, save }: { item: PackageItem | null; close: () => void; save: (item: PackageItem) => void }) {
  const [name, setName] = useState(item?.name ?? '')
  const [origin, setOrigin] = useState(item?.origin ?? 'Buenos Aires')
  const [destination, setDestination] = useState(item?.destination ?? '')
  const [dates, setDates] = useState(item?.dates ?? '')
  const [description, setDescription] = useState(item?.description ?? '')
  const [services, setServices] = useState(item?.services.join('\n') ?? 'Alojamiento seleccionado\nDesayuno diario')
  const [flights, setFlights] = useState(item?.flights ?? 'A coordinar con el agente')
  const [transfer, setTransfer] = useState(item?.transfer ?? 'Traslados según itinerario')
  const [excursions, setExcursions] = useState(item?.excursions.join('\n') ?? 'Experiencia principal en destino')
  const [itinerary, setItinerary] = useState(item?.itinerary.join('\n') ?? 'Día 1 · Llegada y bienvenida\nDía 2 · Experiencia local\nDía 3 · Regreso')
  const [currency, setCurrency] = useState<Currency>(item?.currency ?? 'ARS')
  const [double, setDouble] = useState(String(item?.priceDouble ?? ''))
  const [single, setSingle] = useState(String(item?.priceSingle ?? ''))
  const [pax, setPax] = useState(String(item?.paxTotal ?? ''))
  const [error, setError] = useState('')
  const submit = (event: FormEvent) => { event.preventDefault(); if (!name.trim() || !destination.trim() || !dates.trim() || !double || !pax) return setError('Completá nombre, destino, fechas, precio base doble y cupo total.');
    if (Number(double) <= 0 || Number(pax) < (item ? item.paxTotal - item.seatsLeft : 1)) return setError('El precio debe ser mayor a cero y el cupo no puede quedar debajo de las reservas existentes.')
    const detailFields = { itinerary: itinerary.split('\n').map(value => value.trim()).filter(Boolean), services: services.split('\n').map(value => value.trim()).filter(Boolean), flights, transfer, excursions: excursions.split('\n').map(value => value.trim()).filter(Boolean) }
    const next: PackageItem = item ? { ...item, name, origin, destination, dates, description, currency, ...detailFields, priceDouble: Number(double), priceSingle: Number(single || 0), paxTotal: Number(pax), seatsLeft: item.seatsLeft + Number(pax) - item.paxTotal } : { id: newId('pkg'), name, origin, destination, dates, description, currency, ...detailFields, priceDouble: Number(double), priceSingle: Number(single || 0), paxTotal: Number(pax), seatsLeft: Number(pax), type: 'Experiencia · A medida', costs: Math.round(Number(double) * 0.68), published: false, theme: 'patagonia' }
    if (next.priceDouble < 0 || next.priceSingle < 0 || next.paxTotal < 1) return setError('Los precios y el cupo deben ser valores positivos.'); save(next)
  }
  return <div className="modal-backdrop" onMouseDown={close}><section className="modal package-modal" onMouseDown={event => event.stopPropagation()}><div className="modal-head"><div><p className="eyebrow">TU COLECCIÓN</p><h2>{item ? 'Editar paquete' : 'Crear un paquete'}</h2><p>Un viaje cerrado, listo para compartir.</p></div><button className="icon-button" onClick={close} aria-label="Cerrar"><X size={18} /></button></div><form onSubmit={submit}><div className="form-grid"><label className="full">Nombre del paquete<input autoFocus value={name} onChange={e => setName(e.target.value)} placeholder="Ej. Patagonia Explorer" /></label><label>Origen<input value={origin} onChange={e => setOrigin(e.target.value)} /></label><label>Destino<input value={destination} onChange={e => setDestination(e.target.value)} placeholder="Ciudad o región" /></label><label className="full">Fechas<input value={dates} onChange={e => setDates(e.target.value)} placeholder="12–19 dic 2026" /></label><label className="full">Descripción<textarea value={description} onChange={e => setDescription(e.target.value)} rows={3} placeholder="¿Qué hace especial a este viaje?" /></label><label className="full">Itinerario · un día por línea<textarea value={itinerary} onChange={e => setItinerary(e.target.value)} rows={4} /></label><label className="full">Servicios incluidos · uno por línea<textarea value={services} onChange={e => setServices(e.target.value)} rows={3} /></label><label>Vuelos<input value={flights} onChange={e => setFlights(e.target.value)} /></label><label>Traslado aeropuerto–hotel<input value={transfer} onChange={e => setTransfer(e.target.value)} /></label><label className="full">Excursiones · una por línea<textarea value={excursions} onChange={e => setExcursions(e.target.value)} rows={3} /></label><label>Moneda<select value={currency} onChange={e => setCurrency(e.target.value as Currency)}><option>ARS</option><option>USD</option></select></label><label>Cupo total de viajeros<input type="number" min="1" value={pax} onChange={e => setPax(e.target.value)} /></label><label>Precio por persona · base doble<input type="number" min="1" value={double} onChange={e => setDouble(e.target.value)} /></label><label>Precio por persona · base sencilla<input type="number" min="0" value={single} onChange={e => setSingle(e.target.value)} /></label><p className="form-hint full">La composición del paquete queda protegida al compartirlo. El viajero puede solicitar cambios al agente.</p></div>{error && <p className="form-error">{error}</p>}<div className="modal-actions"><Button variant="ghost" onClick={close}>Cancelar</Button><Button type="submit">{item ? 'Guardar cambios' : 'Crear borrador'} <ArrowRight size={15} /></Button></div></form></section></div>
}

function PackagePreviewModal({ item, close }: { item: PackageItem; close: () => void }) {
  return <div className="modal-backdrop" onMouseDown={close}><section className="modal package-preview-modal" onMouseDown={event => event.stopPropagation()}><div className={`traveler-detail-art art-${item.theme}`}><button className="icon-button" onClick={close} aria-label="Cerrar vista previa"><X size={18} /></button><div className="package-landscape"><i /><b /><em /></div><span><MapPin size={14} />{item.destination}</span></div><div className="traveler-detail-content"><p className="eyebrow">VISTA DEL VIAJERO · {item.dates}</p><h2>{item.name}</h2><p>{item.description}</p><div className="traveler-detail-columns"><div><h3>El itinerario</h3>{item.itinerary.map((day, index) => <div className="itinerary-row" key={day}><span>{String(index + 1).padStart(2, '0')}</span>{day}</div>)}</div><div><h3>Incluye</h3>{item.services.map(service => <p className="include-row" key={service}><Check size={14} />{service}</p>)}<p className="include-row"><Plane size={14} />{item.flights}</p><p className="include-row"><MapPin size={14} />{item.transfer}</p>{item.excursions.map(excursion => <p className="include-row" key={excursion}><Check size={14} />{excursion}</p>)}</div></div><div className="traveler-preview-footer"><span>Desde <b>{money(item.priceDouble, item.currency)}</b> por persona · base doble</span><Button variant="dark" onClick={() => { window.open(`${location.origin}/#viajero/${item.id}`, '_blank', 'noopener,noreferrer'); close() }}>Abrir vista del viajero <ArrowRight size={15} /></Button></div></div></section></div>
}

function BookingDrawer({ state, bookingId, close, update, callBelo, notify, onConversation }: { state: AppState; bookingId: string; close: () => void; update: (fn: (prev: AppState) => AppState) => void; callBelo: (tool: string, args: Record<string, unknown>) => Promise<unknown>; notify: (message: string) => void; onConversation: () => void }) {
  const [note, setNote] = useState('')
  const booking = state.bookings.find(item => item.id === bookingId)
  if (!booking) return null
  const customer = state.customers.find(item => item.id === booking.customerId)
  const pkg = state.packages.find(item => item.id === booking.packageId)
  const requestCancellation = () => { update(prev => ({ ...prev, bookings: prev.bookings.map(item => item.id === booking.id ? { ...item, status: 'Cancelación solicitada', history: [...item.history, 'El viajero solicitó cancelar'] } : item), notices: [{ id: newId('notice'), title: 'Solicitud de cancelación', detail: `${booking.ref} · ${customer?.name}`, time: 'Ahora', read: false }, ...prev.notices] })); notify('Solicitud de cancelación enviada al agente') }
  const decideCancellation = (approve: boolean) => { if (approve && booking.payment === 'Aprobado') void callBelo(BELO_TOOLS.refundPayment, { bookingId: booking.id }); else update(prev => ({ ...prev, bookings: prev.bookings.map(item => item.id === booking.id ? { ...item, status: approve ? 'Cancelada' : 'Confirmada', history: [...item.history, approve ? 'Cancelación aprobada' : 'Cancelación rechazada'] } : item), supplierPayments: prev.supplierPayments.map(row => row.bookingId === booking.id && approve && row.status === 'Pendiente' ? { ...row, status: 'Cancelada' } : row), packages: approve && pkg ? prev.packages.map(row => row.id === pkg.id ? { ...row, seatsLeft: releaseSeats(row.seatsLeft, booking.pax, row.paxTotal) } : row) : prev.packages })); notify(approve ? 'Cancelación aprobada' : 'Solicitud de cancelación rechazada') }
  const addInternalNote = () => { if (!note.trim()) return; update(prev => ({ ...prev, bookings: prev.bookings.map(row => row.id === booking.id ? { ...row, internalNotes: [...(row.internalNotes ?? []), note.trim()] } : row) })); setNote(''); notify('Nota interna agregada') }
  return <div className="drawer-backdrop" onMouseDown={close}><aside className="detail-drawer" onMouseDown={event => event.stopPropagation()}><div className="drawer-top"><button className="icon-button" onClick={close} aria-label="Cerrar"><ArrowLeft size={18} /></button><span>DETALLE DE RESERVA</span><button className="icon-button" onClick={() => navigator.clipboard?.writeText(booking.ref)} aria-label="Copiar código"><Copy size={16} /></button></div><div className="drawer-content"><p className="eyebrow">{booking.ref}</p><h2>{pkg?.name}</h2><p className="drawer-subtitle">{pkg?.destination} · {pkg?.dates}</p><div className="drawer-statuses"><Status>{booking.status}</Status><Status>{booking.payment}</Status></div><div className="drawer-card"><small>VIAJERO</small><button className="drawer-person" onClick={() => notify(`Contacto: ${customer?.email ?? ''} · ${customer?.phone ?? ''}`)}><Avatar initials={customer?.initials ?? '??'} /><span><b>{customer?.name}</b><small>{customer?.email}</small></span><ArrowRight size={15} /></button></div><div className="drawer-info-grid"><div><small>VIAJEROS</small><b>{booking.pax} personas · base {booking.tariff === 'double' ? 'doble' : 'sencilla'}</b></div><div><small>IMPORTE</small><b>{money(booking.amount, booking.currency)}</b></div><div><small>AGENTE ASIGNADO</small><b>{booking.agent}</b></div><div><small>FECHA DE SOLICITUD</small><b>{booking.createdAt}</b></div></div><div className="drawer-card"><small>ACTIVIDAD</small>{booking.history.map((entry, index) => <div className="timeline-row" key={`${entry}-${index}`}><i /><span>{entry}</span></div>)}</div><div className="drawer-card"><small>ESTADO OPERATIVO</small><select className="drawer-status-select" value={booking.status} onChange={event => update(prev => ({ ...prev, bookings: prev.bookings.map(row => row.id === booking.id ? { ...row, status: event.target.value as Booking['status'] } : row) }))}><option value="Solicitada">Solicitada</option><option value="Confirmada">Confirmada</option>{booking.status === "Cancelación solicitada" && <option value="Cancelación solicitada">Cancelación solicitada</option>}{booking.status === "Cancelada" && <option value="Cancelada">Cancelada</option>}</select><p className="demo-caption">El estado del pago se gestiona por separado.</p></div><div className="drawer-card"><small>NOTAS INTERNAS</small>{(booking.internalNotes ?? []).map((entry, index) => <p className="internal-note" key={index}>{entry}</p>)}<textarea value={note} onChange={event => setNote(event.target.value)} placeholder="Solo visible para el equipo" rows={3} /><Button variant="secondary" onClick={addInternalNote}>Guardar nota</Button></div><Button variant="ghost" onClick={onConversation} icon={<MessageCircle size={15} />}>Abrir conversación</Button><div className="drawer-actions">{booking.status === 'Cancelación solicitada' ? <><Button onClick={() => decideCancellation(true)} icon={<Check size={15} />}>Aprobar cancelación</Button><Button variant="secondary" onClick={() => decideCancellation(false)}>Rechazar solicitud</Button>{booking.payment === 'Aprobado' && <p className="warning-copy">Al aprobar, se simulará el reembolso. Los pagos a proveedores ya ejecutados no se revierten.</p>}</> : booking.payment === 'Pendiente' ? <Button onClick={() => notify('El link de pago está disponible desde la ficha del viajero.')} icon={<Link2 size={15} />}>Ver link de pago</Button> : booking.payment === 'Aprobado' && booking.status === 'Confirmada' ? <Button variant="secondary" onClick={requestCancellation}>Solicitar cancelación (viajero)</Button> : null}<Button variant="ghost" onClick={() => navigator.clipboard?.writeText(`${location.origin}/#viajero/${booking.packageId}`)} icon={<ExternalLink size={15} />}>Copiar enlace del paquete</Button></div></div></aside></div>
}

function CustomerDrawer({ state, customerId, close, openBooking }: { state: AppState; customerId: string; close: () => void; openBooking: (id: string) => void }) {
  const customer = state.customers.find(item => item.id === customerId)
  if (!customer) return null
  const bookings = state.bookings.filter(item => item.customerId === customerId)
  return <div className="drawer-backdrop" onMouseDown={close}><aside className="detail-drawer customer-drawer" onMouseDown={event => event.stopPropagation()}><div className="drawer-top"><button className="icon-button" onClick={close} aria-label="Cerrar"><ArrowLeft size={18} /></button><span>FICHA DEL VIAJERO</span><button className="icon-button" onClick={close} aria-label="Cerrar"><X size={17} /></button></div><div className="drawer-content customer-detail"><Avatar initials={customer.initials} tone="sand" /><h2>{customer.name}</h2><p>{customer.email}<br />{customer.phone}</p><div className="drawer-card"><small>NOTAS Y PREFERENCIAS</small><p>{customer.note}</p></div><div className="drawer-card"><small>RESERVAS · {bookings.length}</small>{bookings.map(booking => <button className="related-booking" key={booking.id} onClick={() => openBooking(booking.id)}><span><b>{state.packages.find(pkg => pkg.id === booking.packageId)?.name}</b><small>{booking.ref} · {money(booking.amount, booking.currency)}</small></span><Status>{booking.payment}</Status><ArrowRight size={15} /></button>)}</div><Button variant="secondary" onClick={() => navigator.clipboard?.writeText(customer.email)} icon={<Copy size={15} />}>Copiar correo</Button></div></aside></div>
}

function PiliPanel({ state, page, close, notify }: { state: AppState; page: Page; close: () => void; notify: (message: string) => void }) {
  const [prompt, setPrompt] = useState('')
  const [answer, setAnswer] = useState('Puedo ayudarte con un resumen, un próximo paso o un borrador para responder. Elegí una acción para empezar.')
  const ask = (text: string) => { const pending = state.bookings.filter(item => item.payment === 'Pendiente').length; const active = state.conversations.length; const textLower = text.toLowerCase(); setPrompt(''); setAnswer(textLower.includes('resumen') ? `Hay ${active} conversaciones activas y ${pending} reservas por cobrar. La consulta más reciente es de Mateo Ríos por Iguazú Essential; el paquete tiene 16 lugares disponibles.` : textLower.includes('pago') ? `Veo ${pending} reserva${pending === 1 ? '' : 's'} con pago pendiente. Podés revisar los detalles en Reservas y compartir el link de pago simulado desde la ficha del viajero.` : textLower.includes('paquete') ? `Hay ${state.packages.filter(item => item.published).length} paquetes publicados. ${state.packages.slice(0, 2).map(item => item.name).join(' e ')} tienen disponibilidad en el catálogo.` : `Para ${page === 'overview' ? 'tener una buena vista de tu agencia' : 'avanzar con esta tarea'}, te recomiendo revisar los pendientes y mantener el contacto cercano con tus viajeros. Esta respuesta es una simulación determinista.`); notify('Pili preparó una respuesta contextual') }
  return <aside className="pili-panel"><div className="pili-panel-head"><span className="pili-mark"><Sparkles size={17} /></span><div><b>Pili</b><small>Tu copiloto de operaciones · demo</small></div><button className="icon-button" onClick={close} aria-label="Cerrar Pili"><X size={18} /></button></div><div className="pili-context"><span>CONTEXTO ACTUAL</span><b>{nav.find(item => item.id === page)?.label ?? 'Overview'}</b></div><div className="pili-chat"><div className="pili-welcome"><p className="eyebrow">HOLA, SOFÍA</p><h3>¿Qué podemos<br /><em>resolver hoy?</em></h3><p>Estoy acá para ayudarte a ordenar el próximo paso. Lo que respondo es una simulación local.</p></div><div className="pili-shortcuts"><button onClick={() => ask('resumen')}>Resumir mi actividad <ArrowRight size={14} /></button><button onClick={() => ask('pagos')}>Ver pagos pendientes <ArrowRight size={14} /></button><button onClick={() => ask('paquetes')}>Revisar paquetes publicados <ArrowRight size={14} /></button></div><div className="pili-answer"><span><Sparkles size={13} /> PILI</span><p>{answer}</p></div></div><form className="pili-input" onSubmit={event => { event.preventDefault(); if (prompt.trim()) ask(prompt) }}><input value={prompt} onChange={event => setPrompt(event.target.value)} placeholder="Preguntale algo a Pili…" /><button aria-label="Enviar a Pili"><Send size={16} /></button><small>Respuestas generadas con reglas de demo · sin IA externa</small></form></aside>
}

function Traveler({ state, update, callBelo, notify, onExit, toast, setToast }: { state: AppState; update: (fn: (prev: AppState) => AppState) => void; callBelo: (tool: string, args: Record<string, unknown>) => Promise<unknown>; notify: (title: string, detail: string, whatsapp?: boolean) => void; onExit: () => void; toast: string; setToast: (message: string) => void }) {
  const [query, setQuery] = useState('')
  const [selectedId, setSelectedId] = useState<string | null>(() => location.hash.startsWith('#viajero/') ? decodeURIComponent(location.hash.slice('#viajero/'.length)) : null)
  const [pax, setPax] = useState(2)
  const [tariff, setTariff] = useState<'double' | 'single'>('double')
  const [step, setStep] = useState<'browse' | 'checkout' | 'paid'>('browse')
  const [method, setMethod] = useState('link')
  const [chatMessage, setChatMessage] = useState('')
  const [chatHistory, setChatHistory] = useState([{ from: 'pili', text: '¡Hola! Soy Pili, la asistente de Estudio Nómade. ¿A dónde te gustaría viajar y en qué fechas?' }])
  const selected = state.packages.find(item => item.id === selectedId)
  const cartBooking = state.cart ? state.bookings.find(item => item.id === state.cart?.bookingId) : undefined
  const choices = state.packages.filter(item => item.published && !item.archived && item.seatsLeft > 0 && (!query || `${item.name} ${item.destination} ${item.dates}`.toLowerCase().includes(query.toLowerCase())))
  const priceFor = (pkg: PackageItem) => (tariff === 'double' || !pkg.priceSingle ? pkg.priceDouble : pkg.priceSingle) * pax
  const sendChat = (event: FormEvent) => { event.preventDefault(); if (!chatMessage.trim()) return; const message = chatMessage.trim(); const lowerMessage = message.toLowerCase(); const match = state.packages.find(pkg => `${pkg.destination} ${pkg.name}`.toLowerCase().split(/[^a-záéíóúñ0-9]+/).filter(token => token.length > 2).some(token => lowerMessage.includes(token))); setQuery(match?.destination.split(' · ')[0] ?? message); setChatHistory(prev => [...prev, { from: 'traveler', text: message }, { from: 'pili', text: match ? `Encontré ${match.name}, una experiencia cerrada de ${match.dates}. Te muestro el itinerario y las condiciones para que lo revises.` : 'Voy a revisar las opciones disponibles en nuestro catálogo. Podés usar el buscador para indicarme un destino como Patagonia, Iguazú, Atacama o Rio.' }]); setChatMessage('') }
  const confirmPackage = () => {
    if (!selected) return
    if (pax > selected.seatsLeft) return setToast('La cantidad supera los lugares disponibles.')
    const customer = state.customers[0]
    const amount = priceFor(selected)
    const bookingId = newId('book')
    const booking: Booking = { id: bookingId, ref: `PLS-${Math.floor(2100 + Math.random() * 700)}`, customerId: customer.id, packageId: selected.id, pax, tariff, amount, currency: selected.currency, payment: 'Pendiente', status: 'Confirmada', agent: 'Sofía Méndez', createdAt: new Date().toISOString().slice(0, 10), supplierIds: selected.theme === 'patagonia' ? ['sup-1', 'sup-2'] : selected.theme === 'iguazu' ? ['sup-3'] : selected.theme === 'desert' ? ['sup-4', 'sup-5'] : ['sup-6'], history: ['Paquete confirmado por el viajero', 'Notificación enviada a la agencia · UI y WhatsApp simulados'], internalNotes: [] }
    try { seatsAfterConfirmation(selected.seatsLeft, pax) } catch (error) { return setToast(error instanceof Error ? error.message : 'Sin disponibilidad') }
    update(prev => ({ ...prev, packages: prev.packages.map(item => item.id === selected.id ? { ...item, seatsLeft: item.seatsLeft - pax } : item), bookings: [booking, ...prev.bookings], cart: { bookingId: booking.id, pax, tariff, customerId: customer.id }, notices: [{ id: newId('notice'), title: 'Paquete confirmado', detail: `${customer.name} · ${selected.name} · WhatsApp simulado`, time: 'Ahora', read: false }, ...prev.notices], conversations: prev.conversations.map(row => row.customerId === customer.id ? { ...row, packageId: selected.id, updated: 'Ahora' } : row) }))
    notify('Paquete confirmado', `${customer.name} confirmó ${selected.name}`, true)
    setStep('checkout')
  }
  const createSupplierRows = (booking: Booking, pkg: PackageItem) => {
    const suppliers = booking.supplierIds
    return suppliers.map((supplierId, index) => ({ id: newId('sp'), bookingId: booking.id, supplierId, concept: index === 0 ? `Servicios principales · ${pkg.name}` : `Excursiones y traslados · ${pkg.name}`, amount: Math.round(pkg.costs * booking.pax / suppliers.length), currency: pkg.currency, destination: state.suppliers.find(s => s.id === supplierId)?.currency === 'USD' ? state.suppliers.find(s => s.id === supplierId)?.alias ?? '' : state.suppliers.find(s => s.id === supplierId)?.cbu ?? '', status: 'Pendiente' as const }))
  }
  const simulatePayment = async (approved: boolean) => {
    if (!state.cart) return
    const booking = state.bookings.find(row => row.id === state.cart?.bookingId)
    if (!booking) return setToast('No encontramos la reserva de este carrito.')
    if (booking.payment === 'Aprobado') return setToast('Esta reserva ya está pagada. No se generará otro cobro.')
    if (booking.payment === 'Reembolsado') return setToast('Esta reserva fue reembolsada. Iniciá una nueva reserva para volver a pagar.')
    if (method === 'link') await callBelo(BELO_TOOLS.createPaymentLink, { bookingId: booking.id })
    if (method === 'qr') await callBelo(BELO_TOOLS.createQrPayment, { bookingId: booking.id })
    if (method === 'transfer') await callBelo(BELO_TOOLS.getTransferInstructions, { bookingId: booking.id })
    const pkg = state.packages.find(item => item.id === booking.packageId)
    const settlement = paymentSettlement(booking.amount)
    const fee = settlement.fee
    const supplierRows = approved && pkg ? createSupplierRows(booking, pkg) : []
      update(prev => ({ ...prev, bookings: prev.bookings.map(item => item.id === booking.id ? { ...item, payment: approved ? 'Aprobado' : 'Rechazado', status: approved ? 'Confirmada' : 'Solicitada', history: [...item.history, approved ? 'Pago aprobado mediante Belo simulado' : 'Pago rechazado · el viajero puede intentar nuevamente'] } : item), balances: approved ? { ...prev.balances, [booking.currency]: prev.balances[booking.currency] + settlement.credited } : prev.balances, transactions: approved ? [{ id: newId('tx'), date: new Date().toISOString().slice(0, 10), kind: 'Cobro de viajero', detail: `${pkg?.name} · ${booking.ref}`, amount: booking.amount, currency: booking.currency, status: 'Aprobado', bookingId: booking.id }, { id: newId('tx'), date: new Date().toISOString().slice(0, 10), kind: 'Comisión Piluso (1%)', detail: booking.ref, amount: -fee, currency: booking.currency, status: 'Procesado', bookingId: booking.id }, ...prev.transactions] : [...prev.transactions], supplierPayments: [...supplierRows, ...prev.supplierPayments], notices: [{ id: newId('notice'), title: approved ? 'Pago aprobado' : 'Pago rechazado', detail: `${pkg?.name} · ${booking.ref} · WhatsApp simulado`, time: 'Ahora', read: false }, ...prev.notices] }))
    notify(approved ? 'Pago aprobado' : 'Pago rechazado', `${pkg?.name} · ${booking.ref}`, true)
    if (approved) setStep('paid'); else setToast('El pago fue rechazado en la demo. Podés intentar otra vez.')
  }
  const requestChanges = () => { update(prev => ({ ...prev, conversations: [{ id: newId('conv'), customerId: prev.customers[0].id, channel: 'Web', packageId: selected?.id, assigned: 'Sofía Méndez', mode: 'Agente', status: 'Abierta', updated: 'Ahora', messages: [{ id: newId('msg'), from: 'customer', text: `Quisiera consultar cambios para ${selected?.name ?? 'mi viaje'}.`, time: timeNow() }] }, ...prev.conversations], notices: [{ id: newId('notice'), title: 'Solicitud de personalización', detail: `${prev.customers[0].name} quiere hablar con el agente.`, time: 'Ahora', read: false }, ...prev.notices] })); notify('Solicitud de personalización', 'Un agente recibió tu consulta', true); setToast('Un agente de viajes continuará la conversación.'); setSelectedId(null) }
  const requestCancellation = () => { const booking = state.cart && state.bookings.find(row => row.id === state.cart?.bookingId); if (!booking) return setToast('No hay una reserva asociada para cancelar.'); update(prev => ({ ...prev, bookings: prev.bookings.map(row => row.id === booking.id ? { ...row, status: 'Cancelación solicitada', history: [...row.history, 'El viajero solicitó cancelar'] } : row), notices: [{ id: newId('notice'), title: 'Solicitud de cancelación', detail: `${booking.ref} · revisión del agente pendiente`, time: 'Ahora', read: false }, ...prev.notices] })); notify('Solicitud de cancelación', booking.ref, true); setToast('La agencia recibió tu solicitud. Un agente te responderá pronto.') }
  const removeCart = () => { if (!state.cart || !cartBooking) return; const pkg = state.packages.find(item => item.id === cartBooking.packageId); update(prev => ({ ...prev, cart: undefined, bookings: prev.bookings.map(row => row.id === cartBooking.id ? { ...row, status: 'Cancelada', history: [...row.history, 'Reserva retirada del carrito'] } : row), packages: pkg ? prev.packages.map(row => row.id === pkg.id ? { ...row, seatsLeft: releaseSeats(row.seatsLeft, cartBooking.pax, row.paxTotal) } : row) : prev.packages })); setStep('browse'); setToast('Reserva retirada y lugares liberados.') }
  return <div className="traveler-page"><header className="traveler-header"><Logo /><div><span>ESTUDIO NÓMADE</span><b>Un viaje empieza con una conversación.</b></div><div className="traveler-header-right"><span><ShieldCheck size={14} /> Compra protegida</span><button className="icon-button" onClick={onExit} aria-label="Salir de vista viajero"><LogOut size={17} /></button></div></header><main className="traveler-main"><div className="traveler-intro"><p className="eyebrow">UN VIAJE HECHO PARA VOS</p><h1>Encontrá tu próximo<br /><em>lugar en el mundo.</em></h1><p>Viajá con la tranquilidad de tener a alguien cerca, cuidando cada detalle.</p></div><div className="traveler-chat"><div className="traveler-chat-head"><span className="pili-mark"><Sparkles size={15} /></span><div><b>Una charla con Pili</b><small>Asistente de viajes · simulación</small></div><span className="chat-online"><i /> Disponible</span></div><div className="traveler-chat-messages">{chatHistory.slice(-4).map((item, index) => <div key={`${item.text}-${index}`} className={`traveler-bubble ${item.from}`}>{item.text}</div>)}</div><form className="traveler-chat-form" onSubmit={sendChat}><input value={chatMessage} onChange={e => setChatMessage(e.target.value)} placeholder="Quiero viajar a…" /><button aria-label="Enviar consulta"><Send size={16} /></button></form></div>
    {step === 'browse' && <><div className="traveler-section-head"><div><p className="eyebrow">NUESTROS VIAJES</p><h2>Ideas para empezar</h2></div><div className="search-field"><Search size={15} /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Destino o experiencia" /></div></div><div className="traveler-package-list">{choices.map(pkg => <article className="traveler-package" key={pkg.id}><div className={`traveler-package-art art-${pkg.theme}`}><div className="package-landscape"><i /><b /><em /></div><span><MapPin size={14} />{pkg.destination}</span></div><div className="traveler-package-copy"><span className="eyebrow">{pkg.type.toUpperCase()}</span><h3>{pkg.name}</h3><p>{pkg.description}</p><div className="package-meta"><span><CalendarDays size={14} />{pkg.dates}</span><span><Users size={14} />{pkg.seatsLeft} lugares</span></div><div className="traveler-package-bottom"><span>Desde <b>{money(pkg.priceDouble, pkg.currency)}</b><small>por persona · base doble</small></span><Button variant="dark" onClick={() => { setSelectedId(pkg.id); setPax(Math.min(2, pkg.seatsLeft)); setTariff('double') }}>Ver viaje <ArrowRight size={15} /></Button></div></div></article>)}</div>{!choices.length && <EmptyState title="No encontramos opciones" description="Probá con otro destino o consultale a Pili para que te ayude." />}{state.cart && <button className="traveler-existing-booking" onClick={() => setStep('checkout')}><CreditCard size={16} /> Continuar con tu reserva pendiente <ArrowRight size={15} /></button>}</>}
    {selected && step === 'browse' && <div className="modal-backdrop" onMouseDown={() => setSelectedId(null)}><section className="modal traveler-detail-modal" onMouseDown={event => event.stopPropagation()}><div className={`traveler-detail-art art-${selected.theme}`}><button className="icon-button" onClick={() => setSelectedId(null)} aria-label="Cerrar"><X size={18} /></button><div className="package-landscape"><i /><b /><em /></div><span><MapPin size={14} />{selected.destination}</span></div><div className="traveler-detail-content"><p className="eyebrow">{selected.type.toUpperCase()} · {selected.dates}</p><h2>{selected.name}</h2><p>{selected.description}</p><div className="traveler-detail-columns"><div><h3>El itinerario</h3>{selected.itinerary.map((day, index) => <div className="itinerary-row" key={day}><span>{String(index + 1).padStart(2, '0')}</span>{day}</div>)}</div><div><h3>Incluye</h3>{selected.services.map(service => <p className="include-row" key={service}><Check size={14} />{service}</p>)}<p className="include-row"><Plane size={14} />{selected.flights}</p><p className="include-row"><MapPin size={14} />{selected.transfer}</p></div></div><div className="locked-note"><ShieldCheck size={17} /><span><b>Un viaje, tal como fue pensado.</b><small>Si querés ajustar algo, un agente de viajes puede ayudarte a revisar las opciones.</small></span><button className="text-button" onClick={requestChanges}>Solicitar cambios</button></div><div className="traveler-confirm-row"><label>Pasajeros<select value={pax} onChange={e => setPax(Number(e.target.value))}>{Array.from({ length: selected.seatsLeft }, (_, index) => index + 1).map(value => <option key={value}>{value}</option>)}</select></label><label>Tarifa<select value={tariff} onChange={e => setTariff(e.target.value as 'double' | 'single')}><option value="double">Base doble · {money(selected.priceDouble, selected.currency)} / persona</option>{selected.priceSingle > 0 && <option value="single">Base sencilla · {money(selected.priceSingle, selected.currency)} / persona</option>}</select></label><Button variant="dark" onClick={confirmPackage}>Confirmar paquete · {money(priceFor(selected), selected.currency)} <ArrowRight size={15} /></Button></div></div></section></div>}
    {step === 'checkout' && <section className="traveler-checkout"><div className="checkout-heading"><p className="eyebrow">TU VIAJE, UN PASO MÁS CERCA</p><h2>Revisá tu reserva</h2><p>La composición del paquete está confirmada. Elegí cómo querés realizar el pago.</p></div>{cartBooking && <div className="checkout-grid"><div className="panel checkout-summary"><span className="eyebrow">RESERVA {cartBooking.ref}</span><h3>{state.packages.find(item => item.id === cartBooking.packageId)?.name}</h3><p>{state.packages.find(item => item.id === cartBooking.packageId)?.destination} · {state.packages.find(item => item.id === cartBooking.packageId)?.dates}</p><div className="checkout-summary-line"><span>{cartBooking.pax} pasajeros · base {cartBooking.tariff === 'double' ? 'doble' : 'sencilla'}</span><b>{money(cartBooking.amount, cartBooking.currency)}</b></div><div className="checkout-summary-line"><span>Comisión de servicio</span><span>Incluida</span></div><div className="checkout-total"><span>Total a pagar</span><b>{money(cartBooking.amount, cartBooking.currency)}</b></div><div className="checkout-secure"><ShieldCheck size={17} /> Pago simulado y protegido por Belo</div></div><div className="panel payment-method-panel"><h3>Elegí el medio de pago</h3>{[{ id: 'link', label: 'Link de pago', icon: <Link2 size={17} />, desc: 'Continuá con tu billetera' }, { id: 'qr', label: 'Código QR', icon: <QrCode size={17} />, desc: 'Escanealo desde tu app' }, { id: 'transfer', label: 'Transferencia', icon: <Landmark size={17} />, desc: 'Usá alias o datos bancarios' }].map(item => <button key={item.id} onClick={() => setMethod(item.id)} className={`method-option ${method === item.id ? 'selected' : ''}`}><span className="method-icon">{item.icon}</span><span><b>{item.label}</b><small>{item.desc}</small></span><i /></button>)}<Button variant="dark" onClick={() => void simulatePayment(true)}>Simular pago aprobado <ArrowRight size={15} /></Button><Button variant="secondary" onClick={() => void simulatePayment(false)}>Simular pago rechazado</Button><button className="text-button cancellation-link" onClick={requestCancellation}>Solicitar cancelación</button>{cartBooking.payment !== 'Aprobado' && <button className="text-button cancellation-link" onClick={removeCart}>Quitar reserva y liberar lugares</button>}</div></div>}<button className="text-button back-to-trips" onClick={() => setStep('browse')}><ArrowLeft size={14} /> Volver a explorar</button></section>}
    {step === 'paid' && <section className="payment-success"><span className="success-check"><Check size={28} /></span><p className="eyebrow">RESERVA CONFIRMADA</p><h2>Tu viaje ya empieza.</h2><p>El pago se registró en esta demo y la agencia fue notificada. Te esperamos con todo listo.</p><div className="success-ref"><span>REFERENCIA</span><b>{cartBooking?.ref}</b><Status>Aprobado</Status></div><Button variant="dark" onClick={() => setStep('browse')}>Seguir explorando <ArrowRight size={15} /></Button>{cartBooking?.payment === 'Aprobado' && <button className="text-button cancellation-link" onClick={requestCancellation}>Solicitar cancelación de esta reserva</button>}</section>}
    <footer className="traveler-footer"><Logo /><span>Tu próxima historia empieza acá.</span><span>© 2026 Estudio Nómade · Experiencia de demostración</span></footer></main>{toast && <div className="toast"><Check size={16} />{toast}<button onClick={() => setToast('')}><X size={14} /></button></div>}</div>
}

export default App



